-- UFABC NÃO FOGE À LUTA! — SUPABASE
-- Execute este arquivo inteiro em Supabase > SQL Editor > New query.
-- ATENÇÃO: o login só é seguro porque as permissões são impostas aqui no servidor.

create table if not exists public.site_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  added_at timestamptz not null default now()
);

create table if not exists public.proposals (
  id bigint generated by default as identity primary key,
  title text not null check (char_length(title) between 5 and 150),
  category text not null check (category in (
    'R.U.','Auxílios','Chutes','Cultura','Esportes','Acessibilidade',
    'Mulheres','Étnico-racial','Moradia','Transporte','Infraestrutura','Participação',
    'Permanência','Formação','Diversidade','Democracia','Outros'
  )),
  description text not null check (char_length(description) between 15 and 2000),
  is_published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Atualização segura para quem já executou a versão anterior do schema.
-- O CHECK original é nomeado proposals_category_check pelo PostgreSQL.
alter table public.proposals drop constraint if exists proposals_category_check;
alter table public.proposals add constraint proposals_category_check
check (category in ('R.U.','Auxílios','Chutes','Cultura','Esportes','Acessibilidade','Mulheres','Étnico-racial','Moradia','Transporte','Infraestrutura','Participação','Permanência','Formação','Diversidade','Democracia','Outros'));

create or replace function public.set_proposal_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at = now();
  return new;
end; $$;

drop trigger if exists proposal_set_updated_at on public.proposals;
create trigger proposal_set_updated_at
before update on public.proposals
for each row execute function public.set_proposal_updated_at();

alter table public.proposals enable row level security;
alter table public.site_admins enable row level security;

-- RLS consulta administradores, mas ninguém consegue cadastrar a si mesmo.
-- Somente o dono do projeto, no SQL Editor, registra administradores.
drop policy if exists "Read own admin membership" on public.site_admins;
create policy "Read own admin membership"
on public.site_admins for select to authenticated
using (user_id = (select auth.uid()));

-- Qualquer visitante pode ver propostas PUBLICADAS.
-- Administradores também podem consultar rascunhos.
drop policy if exists "Read published proposals or own admin drafts" on public.proposals;
create policy "Read published proposals or own admin drafts"
on public.proposals for select to anon, authenticated
using (
  is_published = true
  or exists(select 1 from public.site_admins a where a.user_id = (select auth.uid()))
);

-- Só usuários do grupo de administradores podem escrever.
drop policy if exists "Admin can insert proposals" on public.proposals;
create policy "Admin can insert proposals"
on public.proposals for insert to authenticated
with check (exists(select 1 from public.site_admins a where a.user_id = (select auth.uid())));

drop policy if exists "Admin can update proposals" on public.proposals;
create policy "Admin can update proposals"
on public.proposals for update to authenticated
using (exists(select 1 from public.site_admins a where a.user_id = (select auth.uid())))
with check (exists(select 1 from public.site_admins a where a.user_id = (select auth.uid())));

drop policy if exists "Admin can delete proposals" on public.proposals;
create policy "Admin can delete proposals"
on public.proposals for delete to authenticated
using (exists(select 1 from public.site_admins a where a.user_id = (select auth.uid())));

-- Permissões básicas de API. RLS continua controlando QUAIS linhas podem ser acessadas.
grant usage on schema public to anon, authenticated;
revoke all on public.site_admins from anon, authenticated;
grant select on public.proposals to anon;
grant select, insert, update, delete on public.proposals to authenticated;
grant select on public.site_admins to authenticated;
grant usage, select on sequence public.proposals_id_seq to authenticated;

-- Propostas informadas pela chapa (53 itens) agrupadas por eixo.
-- Importação segura contra títulos duplicados, mesmo executando este arquivo mais de uma vez.
-- Se o projeto já contém os EXEMPLOS INICIAIS da versão anterior, removê-los só se
-- tiverem exatamente o título e a descrição originais; NÃO remove propostas editadas.
delete from public.proposals p
where (p.title,p.description) in (
  ('Permanência para continuar e concluir','Defender o fortalecimento das políticas de assistência estudantil, com atenção às condições de quem trabalha, estuda e enfrenta dificuldades para permanecer na UFABC.'),
  ('Moradia estudantil é pauta central','Ampliar o debate e a mobilização por políticas de moradia, acolhimento e apoio a estudantes que precisam morar perto dos campi.'),
  ('Formação com qualidade e acolhimento','Defender melhores condições de ensino, apoio acadêmico, escuta dos estudantes e enfrentamento das dificuldades que levam à retenção e à evasão.'),
  ('Uma UFABC antirracista e sem LGBTfobia','Cobrar acolhimento, apuração responsável das denúncias de discriminação e medidas institucionais concretas para garantir respeito e dignidade.'),
  ('Cultura negra, integração e pertencimento','Promover oficinas, encontros, debates e atividades culturais que fortaleçam a integração, a valorização das culturas negras e a permanência estudantil.'),
  ('Acessibilidade e permanência para todos','Lutar por acessibilidade física, pedagógica e comunicacional, com atenção às demandas das pessoas com deficiência e neurodivergentes.'),
  ('Mais participação nas decisões da universidade','Aproximar o DCE do cotidiano estudantil, ampliar espaços de diálogo e dar transparência às pautas e encaminhamentos da representação.')
);

